int oddCount = 0;
std::random_device rd;
std::mt19937 gen(rd());
std::uniform_real_distribution<double> dis(-1.0, 1.0);

for (int i = 0; i < numberOfChecks; i++) {
    // Generate a random direction vector
    double dx = dis(gen);
    double dy = dis(gen);
    double dz = dis(gen);
    double length = std::sqrt(dx*dx + dy*dy + dz*dz);
    if (length < 1e-10) continue; // Avoid zero-length ray
    dx /= length; dy /= length; dz /= length;

    // Create ray from point p in random direction
    cg3::cgal::AABBTree3::CGALPoint rayOrigin(p.x(), p.y(), p.z());
    cg3::cgal::AABBTree3::CGALPoint rayDirection(p.x() + dx, p.y() + dy, p.z() + dz);
    cg3::cgal::AABBTree3::CGALRay ray(rayOrigin, rayDirection);

    // Count intersections with the mesh
    std::vector<cg3::cgal::AABBTree3::CGALTriangle> intersections;
    tree.number_intersections(ray, std::back_inserter(intersections));

    // If odd number of intersections, point is inside
    if (intersections.size() % 2 == 1) {
        oddCount++;
    }
}

// If majority of rays indicate inside, return true
return oddCount > numberOfChecks / 2;

